// Polled acquisition (ADR-0018): Siemens S7 (S7 communication, PUT/GET) and
// Rockwell Logix controllers (EtherNet/IP, tag names). One connection per
// source in the model, read every pollIntervalMs. Read-only: never writes.
// Input: the list of sources from "build model cache". Output 1: one message
// per value that changed, or that is due again (max_publish_interval_ms).
// Output 2: one message per source connection change.
// PLCs send no timestamps, so values are stamped by this gateway (ADR-0003).
const POLLED = ["s7", "ethernetip"];
const BACKOFF_MS = [1000, 2000, 5000, 10000];         // wait before reconnecting
const OPEN_TIMEOUT_MS = 5000;

// A new model replaces all connections.
for (const s of Object.values(context.get("sources") || {})) s.stop();
const sources = {};
context.set("sources", sources);

const list = (msg.payload || []).filter(s => POLLED.includes(s.protocol));
if (list.length === 0) return null;

function report(st, online, error) {
    if (st.online === online) return;                  // only changes
    st.online = online;
    node.send([null, { payload: { source: st.name, online, error } }]);
    const off = Object.values(sources).filter(s => !s.online).map(s => s.name);
    node.status(off.length ? { fill: "red", shape: "ring", text: "offline: " + off.join(", ") }
                           : { fill: "green", shape: "dot", text: Object.keys(sources).length + " PLC(s) online" });
}

function hostPort(endpoint, defaultPort) {
    const m = /^\s*([^:\s]+)(?::(\d+))?\s*$/.exec(String(endpoint || ""));
    if (!m) throw new Error("endpoint must be an IP address or host name, optionally :port");
    return { host: m[1], port: m[2] ? Number(m[2]) : defaultPort };
}

function withTimeout(promise, ms, what) {
    let timer;
    return Promise.race([
        promise,
        new Promise((_, reject) => { timer = setTimeout(() => reject(new Error(what + ": no answer within " + ms / 1000 + " s")), ms); })
    ]).finally(() => clearTimeout(timer));
}

function describe(e) {
    if (!e) return "unknown error";
    if (e.message) return e.message;
    if (e.generalStatusCode !== undefined) return "CIP status " + e.generalStatusCode;   // EtherNet/IP
    return String(e);
}

// One driver per protocol: open a connection; probe one address (throws if
// it cannot be read); read a list of good addresses in as few requests as
// the protocol allows.
const drivers = {
    s7: async (src, settings) => {
        const lib = global.get("s7");
        if (!lib) throw new Error("S7 library is not available (see nodered/settings.js)");
        const { host, port } = hostPort(src.endpoint, 102);
        const ep = new lib.S7Endpoint({
            host, port,
            rack: Number.isInteger(settings.rack) ? settings.rack : 0,
            slot: Number.isInteger(settings.slot) ? settings.slot : 1,
            autoReconnect: 0                                // reconnecting is done below
        });
        ep.on("error", () => { /* reported by the next read */ });
        await withTimeout(ep.connect(), OPEN_TIMEOUT_MS, "connect to " + host);
        const probeGroup = new lib.S7ItemGroup(ep);
        let group = null, groupKey = null;
        return {
            probe: async address => {
                probeGroup.addItems(address);               // throws on a malformed address
                try { await probeGroup.readAllItems(); } finally { probeGroup.removeItems(address); }
            },
            read: async addresses => {
                const key = addresses.join("\n");
                if (key !== groupKey) {
                    group = new lib.S7ItemGroup(ep);
                    group.addItems(addresses);
                    groupKey = key;
                }
                const r = await group.readAllItems();
                return addresses.map(a => r[a]);
            },
            connected: () => ep.isConnected,
            close: () => ep.disconnect().catch(() => { /* already closed */ })
        };
    },
    ethernetip: async (src, settings) => {
        const lib = global.get("ethernetip");
        if (!lib) throw new Error("EtherNet/IP library is not available (see nodered/settings.js)");
        const { host } = hostPort(src.endpoint, 44818);
        const plc = new lib.Controller(true);           // connected messaging
        plc.timeout_sp = 3000;
        plc.on("error", () => { /* reported by the next read */ });
        // false: do not upload the controller's tag list; atomic tags only.
        await withTimeout(plc.connect(host, Number.isInteger(settings.slot) ? settings.slot : 0, false),
                          OPEN_TIMEOUT_MS, "connect to " + host);
        let tags = null, group = null, groupKey = null;
        return {
            probe: async address => {
                if (!lib.Tag.isValidTagname(address)) throw new Error("not a valid Logix tag name");
                await plc.readTag(new lib.Tag(address));
            },
            read: async addresses => {
                const key = addresses.join("\n");
                if (key !== groupKey) {
                    tags = addresses.map(a => new lib.Tag(a));
                    group = new lib.TagGroup();
                    tags.forEach(t => group.add(t));
                    groupKey = key;
                }
                if (tags.length === 1) await plc.readTag(tags[0]);
                else await plc.readTagGroup(group);
                return tags.map(t => t.value);
            },
            connected: () => !plc.destroyed && plc.established !== false,
            close: () => { try { plc.destroy(); } catch (e) { /* already closed */ } }
        };
    }
};

function same(a, b) {
    return a === b || (typeof a === "object" && JSON.stringify(a) === JSON.stringify(b));
}

function start(src) {
    const settings = src.settings || {};
    const pollMs = Math.max(100, Number(settings.pollIntervalMs) || 1000);
    const st = { name: src.name, online: null, stopped: false, conn: null, timer: null };
    sources[src.name] = st;
    st.stop = () => {
        st.stopped = true;
        clearTimeout(st.timer);
        if (st.conn) st.conn.close();
    };
    const last = {};                                    // address -> { value, sentAt }
    let attempt = 0;

    async function session() {
        if (st.stopped) return;
        try {
            st.conn = await drivers[src.protocol](src, settings);
            // Probe each address once, so one wrong address cannot stop the others.
            const good = [];
            for (const item of src.items) {
                try {
                    await st.conn.probe(item.address);
                    good.push(item);
                } catch (e) {
                    if (!st.conn.connected()) throw e;
                    node.warn(src.name + ": " + item.address + ": " + describe(e) + " - not read");
                }
            }
            report(st, true);
            attempt = 0;
            const addresses = good.map(i => i.address);
            if (!addresses.length) {                    // nothing readable: try again in a minute
                await new Promise(r => { st.timer = setTimeout(r, 60000); });
            }
            while (!st.stopped && addresses.length) {
                const t0 = Date.now();
                const values = await st.conn.read(addresses);
                const now = Date.now();
                good.forEach((item, i) => {
                    const prev = last[item.address];
                    const v = values[i];
                    if (prev && same(prev.value, v) && now - prev.sentAt < item.maxIntervalMs) return;
                    last[item.address] = { value: v, sentAt: now };
                    node.send([{ payload: {
                        source: src.name, address: item.address,
                        value: typeof v === "bigint" ? Number(v) : v,
                        status: "Good", sourceTimestamp: null, receivedAt: now
                    } }, null]);
                });
                await new Promise(r => { st.timer = setTimeout(r, Math.max(0, pollMs - (Date.now() - t0))); });
            }
        } catch (e) {
            if (st.stopped) return;
            report(st, false, describe(e));
        }
        if (st.conn) { st.conn.close(); st.conn = null; }
        if (st.stopped) return;
        const wait = BACKOFF_MS[Math.min(attempt++, BACKOFF_MS.length - 1)];
        st.timer = setTimeout(session, wait);
    }
    session();                                          // runs in the background
}

for (const src of list) start(src);
return null;

finalize:
// Close every PLC connection when the flow is stopped or redeployed.
for (const s of Object.values(context.get("sources") || {})) s.stop();
context.set("sources", {});

func:
// One value change in, the canonical OFM messages out (Overview §7.1).
// Output 1: live value to the UNS. Output 2: historian row (numbers, booleans).
// Output 3: historian row (text). Output 4: quarantine and cache status.
const SKEW_MS = 5 * 60 * 1000;                      // ADR-0003: future-skew limit
const OLDEST = Date.UTC(2020, 0, 1);                 // older device time = clock not set
const v = msg.payload;
const model = global.get("ofm_model");
const key = v.source + "|" + v.address;
const p = model && model.byKey[key];

// --- timestamp and provenance (ADR-0003) -----------------------------------
let ts = v.sourceTimestamp, tss = "device", q = qualityOf(v.status);
if (!Number.isFinite(ts) || ts < OLDEST) {
    if (Number.isFinite(ts)) q = worst(q, "uncertain");   // device clock not set
    ts = v.receivedAt; tss = "gateway";
} else if (ts > v.receivedAt + SKEW_MS) {
    ts = v.receivedAt; tss = "gateway"; q = worst(q, "uncertain");
}
ts = Math.round(ts);

// --- not in the model: quarantine (ADR-0001) --------------------------------
if (!p) {
    const unmapped = global.get("ofm_unmapped") || {};
    const isNew = !unmapped[key];
    unmapped[key] = true;
    global.set("ofm_unmapped", unmapped);
    const out = [{
        topic: "ofm/_unmapped/" + v.source + "/" + v.address.replace(/[\/+#]/g, "_"),
        payload: { v: plain(v.value), ts, tss, addr: v.address }, retain: false, qos: 0
    }];
    if (isNew) out.push({
        topic: "ofm/_system/cache/" + env.get("OFM_RUNTIME_NAME"),
        payload: { ts: model ? model.loadedAt : Date.now(), trigger: "startup",
                   rows: model ? Object.keys(model.byProperty).length : 0,
                   unmapped: Object.keys(unmapped).length },
        retain: true, qos: 1
    });
    return [null, null, null, out];
}

// --- value: scale and type ---------------------------------------------------
let value = convert(v.value, p);
if (value === null) q = "bad";
else if (typeof value === "number" &&
         ((p.low !== null && p.low !== undefined && value < p.low) ||
          (p.high !== null && p.high !== undefined && value > p.high))) {
    q = worst(q, "uncertain");                       // outside the engineering range
}

// Backwards device time for the same property is a clock problem (ADR-0003).
const last = context.get("lastTs") || {};
if (last[p.propertyId] !== undefined && ts < last[p.propertyId]) q = worst(q, "uncertain");
last[p.propertyId] = Math.max(ts, last[p.propertyId] || 0);
context.set("lastTs", last);

const live = { topic: p.topic, payload: { v: value, ts, q, tss }, retain: true, qos: 1 };

let numeric = null, text = null;
if (p.historised && value !== null) {
    const row = [ts, p.propertyId, null, ["good", "uncertain", "bad"].indexOf(q), tss === "device" ? 0 : 1];
    if (p.datatype === "string") { row[2] = value; text = { params: row }; }
    else { row[2] = typeof value === "boolean" ? (value ? 1 : 0) : value; numeric = { params: row }; }
}
return [live, numeric, text, null];

// --- helpers ------------------------------------------------------------------
function qualityOf(status) {
    const s = String(status || "Bad");
    return s.startsWith("Good") ? "good" : s.startsWith("Uncertain") ? "uncertain" : "bad";
}
function worst(a, b) {
    const order = ["good", "uncertain", "bad"];
    return order[Math.max(order.indexOf(a), order.indexOf(b))];
}
function plain(raw) {
    if (raw === null || raw === undefined) return null;
    if (typeof raw === "number" || typeof raw === "boolean") return raw;
    return String(raw).slice(0, 1024);
}
function convert(raw, p) {
    if (raw === null || raw === undefined) return null;
    if (p.datatype === "bool") {
        if (typeof raw === "boolean") return raw;
        if (typeof raw === "number") return raw !== 0;
        return null;
    }
    if (p.datatype === "string") return String(raw).slice(0, 1024);
    let n;
    if (Array.isArray(raw) && raw.length === 2) n = raw[0] * 4294967296 + raw[1];   // 64-bit as [high, low]
    else if (typeof raw === "boolean") n = raw ? 1 : 0;
    else n = Number(raw);
    if (!Number.isFinite(n)) return null;
    n = n * p.factor + p.offset;
    return p.datatype === "int" ? Math.round(n) : n;
}

