INSERT INTO hist.measurement (ts, property_id, value, quality, ts_source)
VALUES (to_timestamp($1::double precision / 1000), $2, $3, $4, $5)
ON CONFLICT (property_id, ts) DO NOTHING;

INSERT INTO hist.measurement_text (ts, property_id, value, quality, ts_source)
VALUES (to_timestamp($1::double precision / 1000), $2, $3, $4, $5)
ON CONFLICT (property_id, ts) DO NOTHING;

