// Source connection state, retained, for every consumer (ADR-0007).
const s = msg.payload;
msg.topic = "ofm/_system/sources/" + s.source;
msg.payload = { state: s.online ? "online" : "offline", ts: Date.now() };
if (!s.online && s.error) msg.payload.error = String(s.error).slice(0, 1024);
msg.retain = true;
msg.qos = 1;
return msg;

// When the broker connection comes up (also after a broker restart), announce
// this runtime as online. Its Last Will announces "offline" if it disappears.
const connected = msg.status && msg.status.fill === "green";
if (connected === context.get("connected")) return null;
context.set("connected", connected);
if (!connected) return null;
msg.topic = "ofm/_system/runtime/" + env.get("OFM_RUNTIME_NAME");
msg.payload = { state: "online", ts: Date.now() };
msg.retain = true;
msg.qos = 1;
return msg;
